import java.util.concurrent.Callable
import java.util.concurrent.ExecutorService
import java.util.concurrent.Future

class TaskRunner {
    fun invokeAllBad(executor: ExecutorService, callables: Collection<Callable<String>>): List<Future<String>> {
        return executor.invokeAll(callables)
    }
}

import java.util.concurrent.Callable
import java.util.concurrent.ExecutorService

class AnyRunner {
    fun invokeAnyBad(executor: ExecutorService, callables: Collection<Callable<String>>): String {
        return executor.invokeAny(callables)
    }
}

import java.util.concurrent.Callable
import java.util.concurrent.ExecutorService
import java.util.concurrent.Future
import java.util.concurrent.TimeUnit

class TimedTaskRunner {
    fun invokeAllGood(executor: ExecutorService, callables: Collection<Callable<String>>): List<Future<String>> {
        return executor.invokeAll(callables, 30, TimeUnit.SECONDS)
    }
}

import java.util.concurrent.Callable
import java.util.concurrent.ExecutorService
import java.util.concurrent.TimeUnit

class TimedAnyRunner {
    fun invokeAnyGood(executor: ExecutorService, callables: Collection<Callable<String>>): String {
        return executor.invokeAny(callables, 10, TimeUnit.SECONDS)
    }
}
